C = dict(id='GL-14', title='IT Service and Support', group='Digital and Technology', level=3,
 summary='Run a friendly, organised help desk: take requests, find and fix common faults, write clear guides and measure how well users are served.',
 outcomes=['Explain the support cycle: request, triage, fix, close, learn.', 'Fix ten common faults on phones, computers and networks.', 'Analyse tickets to find repeated problems and their causes.', 'Create a help guide, a ticket form and a simple service promise.', 'Evaluate service quality with response times and user ratings.'],
 task='Run a practice help desk for 20 requests from real or simulated users and report on response times and user ratings.',
 cond='A free ticket tool or spreadsheet, practice computers or phones, a list of common faults, a mentor with support experience and a peer circle. About 8 to 10 weeks part-time.',
 std='Every ticket logged with time stamps; first reply within the promised time for 90% of tickets; at least 7 of 10 faults fixed first time; guide tested by a non-technical user; average rating 4 of 5 or better.',
 who='Anyone starting in IT support, office staff, college learners, returners.', req='Basic computer skills.',
 safety='Never ask users for passwords. Use remote tools only with permission. Back up before you change anything.',
 mods=[
 ('The help desk cycle', 'Good support follows a repeatable cycle.', ['Request logged; priority set; assigned; fixed; closed; reviewed.', 'Priority depends on how many people and how much work is stopped.', 'Always tell the user what happens next and when.', 'Close only when the user agrees.'], 'One user cannot print (low) versus the whole office has no internet (high).', 'Draw the cycle and give two priority examples.', 'Check that the cycle is correct and the examples are sensible.'),
 ('Listening and asking', 'Most faults are solved by good questions.', ['Ask: what happened, what did you expect, what changed lately.', 'Repeat back in your own words.', 'Use plain words, no jargon.', 'Stay calm and kind.'], 'User says "the computer is broken". Questions reveal that only the sound is off; fix in one minute.', 'Role-play three calls with a partner.', 'Obtain a clarity rating of 4 of 5 from your partner.'),
 ('Logging tickets', 'A good ticket lets anyone pick up the case.', ['Fields: who, when, what, steps already tried, priority.', 'One issue per ticket.', 'Time stamps for open, first reply and close.', 'Keep notes short and factual.'], 'Ticket: "Printer 2 offline since 09:10, tried restart, error E12, 4 users affected, priority medium."', 'Create a ticket form and log 10 practice tickets.', 'Complete all tickets with times.'),
 ('Common faults: computers and phones', 'Learn the ten most frequent faults.', ['No power or screen: check cable, battery, display.', 'Slow: storage full, too many programs, updates.', 'No sound or camera: device choice and permissions.', 'Updates and backups; safe removal of unwanted apps.'], 'Storage 98% full: clear downloads, move photos to backup, free 20 GB; speed returns.', 'Fix five practice faults and note steps.', 'Document five fixes.'),
 ('Common faults: network and accounts', 'Connection and sign-in problems cause many tickets.', ['Wi-Fi: forget and rejoin, restart router, check others.', 'Decide if the fault is the name lookup (the step that turns a web address into a machine), the cable or the provider.', 'Password reset safely: verify identity first.', 'Account locked: check cause before unlocking.'], 'Only one laptop cannot connect: others fine; forget network, rejoin; solved.', 'Fix five network or account scenarios.', 'Document the steps with reasoning.'),
 ('Writing guides', 'A guide that works saves the next call.', ['Short steps with a picture each.', 'Test it on someone who is not technical.', 'Put the fix at the top, the cause below.', 'Keep a short list of frequent questions.'], 'Guide: "Join the office Wi-Fi in 5 steps"; three users follow it alone without calling.', 'Write and test one guide.', 'Test that a tester completes it without help.'),
 ('Measure service', 'What gets measured gets better.', ['First reply time; fix time; first-time fix rate; user rating.', 'Group tickets by cause to find repeats.', 'Report weekly in one table.', 'Set a service promise you can keep.'], '20 tickets: 18 first-replied within 30 minutes = 90%; 14 fixed first time = 70%; average rating 4.3.', 'Compute the four measures for your tickets.', 'Calculate all four correctly.'),
 ('Improve and escalate', 'Know your limits and pass on cases well.', ['Escalate with full notes and what you tried.', 'Fix causes, not just symptoms.', 'Thank users and ask for feedback.', 'Plan 90 days of learning.'], 'Three tickets about the same app: ask for an update rather than fix again.', 'Write a problem report and a 90-day plan.', 'Report names cause, fix and owner.')],
 quiz=[('Name the support cycle steps.', 'Log, triage, assign, fix, close, review.'), ('What sets priority?', 'How many people and how much work are stopped.'), ('Why one issue per ticket?', 'It keeps tracking and closing clear.'), ('Why never ask for a password?', 'Support never needs it and asking trains users to give it away.'), ('What is first-time fix rate?', 'Tickets fixed at first attempt divided by all tickets.'), ('How do you test a guide?', 'Have a non-technical user follow it alone.'), ('What first for a slow computer?', 'Check storage, startup programs and updates.'), ('What goes in a good escalation?', 'Full notes and what has been tried.'), ('Why group tickets by cause?', 'To fix repeat problems at the source.'), ('When can you close a ticket?', 'When the user agrees it is fixed.')],
 rubric=[('Communication', 'Clear, kind replies', 'Users rate 4.5 or better'), ('Ticket quality', 'All fields and times', 'Notes let anyone continue'), ('Fix skill', 'Seven of ten first time', 'Causes documented'), ('Guides', 'One tested guide', 'Three guides reduce repeat tickets'), ('Measures', 'Four measures correct', 'Used to change the process')],
 jobs=[('Help desk agent', 'Takes and fixes first-line requests'), ('Desktop support technician', 'Fixes computers and phones on site'), ('Office IT assistant', 'Keeps a small office running'), ('Technical writer assistant', 'Writes help guides')],
 next='Cloud Migration as a Service; Tele and Video Conferencing Operations; Mobile Application Testing Services.',
 local='Check local consumer and data rules when you handle other people\'s devices and accounts.',
 evidence='Your evidence: ticket log of 20, five computer and five network fixes, tested guide, measures table and 90-day plan.',
 ladder=[('Basics of helping', 'Describe what a help desk does and how a user should describe a problem. Notes: write a good request for a broken printer and a poor one, and compare. Standard: the good request has what, where, since when and what was tried.'), ('Awareness', 'Name the main kinds of faults (account, device, network, software) and who should handle each. Notes: sort twenty sample requests into the four kinds. Standard: at least 17 of 20 sorted correctly.'), ('Foundation', "Take a request, ask the right questions, solve a simple fault and write the ticket. Notes: use sample requests such as a locked account or a slow laptop. Standard: each ticket has the problem, the fix, the time and the user's confirmation."), ('Practitioner', 'Handle a queue of requests by priority, keep users informed and escalate with the right detail. Notes: run ten simulated requests with two urgent. Standard: urgent requests first, updates sent on time, escalations complete.'), ('Specialist', 'Run a practice help desk for 20 requests from real or simulated users and report on response times and user ratings. Notes: set targets before you start, such as first reply in 30 minutes. Standard: report shows targets, results, the slowest ticket and a fix.'), ('Advanced', 'Lead a help desk team with a knowledge base, a service target and a monthly review. Notes: add article templates and a repeat-ticket report. Standard: repeat tickets fall month on month, or the report says why not.'), ('Super expert', 'Set the ticket-handling standard (priority, target times, hand-over) and teach the support leads who apply it. Notes: review first-response, resolution and repeat-ticket figures each year.')])

C['deep'] = dict(mods=[
 ('Jumping to fixes before understanding the fault.', 'A "slow computer" is only a full disk; ten minutes of questions saves an hour of rebuilding.', 'What three questions start every call?'),
 ('Using jargon with a worried user.', 'Say "the network is not reaching the printer" not "the print spooler is hung".', 'Rewrite one technical sentence in plain words.'),
 ('A ticket that says only "it\'s broken".', 'Better: "Laptop A12, no Wi-Fi since 09:10, others fine, restarted once, priority medium".', 'Is any of your tickets missing a time?'),
 ('Changing settings before backing up.', 'A reset wipes photos; a backup first saves them.', 'What do you back up before a fix?'),
 ('Unlocking accounts without checking who asks.', 'Verify by a known contact before resetting a password.', 'How do you verify identity?'),
 ('Writing a guide without testing it.', 'A tester gets stuck at step 3; the picture was wrong.', 'Who tested your guide?'),
 ('Reporting only averages.', 'Average 4.3 hides one rating of 1; read the comment.', 'What did your lowest rating say?'),
 ('Escalating without notes.', 'Escalation lists steps tried, error code and time, saving a repeat call.', 'What goes in your escalation note?')],
 gloss=[('Ticket', 'A record of one request.'), ('Triage', 'Sorting by urgency.'), ('First-time fix', 'Solved at the first attempt.'), ('Escalation', 'Passing a case to a higher level.'), ('Root cause', 'The real reason for a fault.'), ('Service promise', 'The reply and fix times you commit to.')],
 cases=[('The whole floor is offline', 'Twenty people lose the network at 10:00.', 'Priority and first steps?', 'High priority; check shared equipment first, tell users, escalate to the provider with notes.'),
        ('The angry caller', 'A user shouts about a lost file.', 'How do you respond?', 'Stay calm, listen, repeat back, say what you will do and when, and check the recycle bin and backups.')])
C['deep']['extra'] = [
 ['Greet the user by name and confirm the best way to reach them.', 'Never blame the user; say "let us check".'],
 ['Use the "five whys" to move from symptom to cause.', 'Ask the user to show you the screen when words fail.'],
 ['Add a category so you can count ticket types later.', 'Record the user\'s device and location, not their passwords.'],
 ['Check cables and power before software.', 'Keep a bootable repair tool and a spare charger in the kit.'],
 ['Test with a second device to decide if the fault is the device or the network.', 'Teach users to restart the router safely.'],
 ['Use short sentences and the same words as the screen.', 'Add a "still stuck?" line with the help desk contact.'],
 ['Chart tickets per week to see peaks.', 'Compare first reply time by hour of day.'],
 ['Thank users and close with a one-line summary of what was done.', 'Hold a monthly review of repeat tickets.']]

_ex = ["A caller says 'the computer is broken'. Three questions show only the sound is muted after an update; the fix takes one minute and the ticket records the cause.", 'Priority: one user cannot print (low, 1 person, work continues) versus the whole floor offline (high, 20 people, work stopped).', "Ticket 0412: 'Laptop A12, no Wi-Fi since 09:10, other devices fine, restarted once, priority medium, owner the on-duty technician'. Another technician can continue without calling the user.", 'Storage is 98% full. You clear downloads, move photos to backup and free 20 GB; speed returns and the ticket notes the cause so the user can repeat it.', 'Only one laptop cannot connect while others work. You forget and rejoin the network, check the saved password, and solve it in 6 minutes.', "A guide titled 'Join the office Wi-Fi in 5 steps' with pictures is followed alone by three non-technical testers, all in under 4 minutes.", 'Of 20 tickets, 18 had a first reply inside 30 minutes (90%) and 14 were fixed first time (70%); the average rating was 4.3 out of 5.', 'Three tickets about the same app lead to a problem report asking for an update rather than three separate fixes.']
_extra = ['Keep a notebook of every new fault and the fix that worked.', 'Practise explaining a fault to someone who has never used a computer.', 'Learn the shortcuts for screenshots, which help ticket notes.', 'Set a standard greeting that is warm and short.', 'Check that every ticket has an owner and a next step.', 'Record the time you first reply to each user.', "Practise saying 'I do not know yet, but I will find out by three o'clock'.", 'Learn how to reset a router safely and tell users what to expect.', 'Check that backups exist before any risky fix.', 'Create a list of the ten most common faults in your setting.', 'Write guides in the same order every time: problem, steps, check.', 'Keep a list of trusted tools and never install unknown ones.', 'Review rating comments weekly and thank those who praised.', 'Hold a short monthly review of repeat problems.', 'Keep your own skills list and add one new fix a week.', 'Share one lesson with the peer circle each month.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Learn the cycle of receive, record, classify, diagnose, fix or escalate, confirm with the user and close, and put it on one page by your desk.', 'Agree target times, such as an acknowledgement within 15 minutes and a first reply within 30 minutes, so users know what to expect.'], ['Open every call with three questions: what were you trying to do, what happened instead, and what changed recently, and write the answers word for word.', 'Use plain words, avoid jargon, and confirm by repeating the key facts back; ask the user to read any error message exactly as shown.'], ["Record who, when, where, device, exact error text, steps to repeat, and what has been tried; keep the title short, such as 'Printer offline, floor 2'.", 'Set priority by impact and number of people affected, for example one person with a workaround is low, a whole team unable to work is high.'], ['Check power and cables first, then restart, then whether free storage has fallen under 10 percent, then recent updates or new software, then run a simple scan.', 'Before changing settings or wiping anything, ask whether the user has recent copies of important files, and note it on the ticket.'], ['Ask whether other devices or colleagues are affected, test with a wired connection or a phone hotspot, and check whether the problem is one account or the whole network.', 'For account problems verify identity first, check lock status and password age, and reset using a one-time method rather than reading passwords aloud.'], ['Write each guide with a title, who it is for, numbered steps of one action each, a screenshot where helpful and a line saying when to contact support.', 'Test the guide with someone who has never seen the task; every question they ask shows a step that needs rewriting.'], ['Track tickets opened and closed per week, average time to first reply, average time to fix, and a one-question satisfaction score out of five.', 'Review the top five repeat causes monthly, and ask whether a guide, a fix or user training would remove each one for good.'], ['Escalate when a ticket passes its target time, needs access you do not have, or affects many people, and always hand over the notes and what has been tried.', 'Hold a 20-minute monthly review of the hardest tickets and agree one change, such as a new guide or a monitoring alert, for each.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {4: "A phone shows 'cannot take photos' because storage is full. You move 300 photos to a backup, delete cached files, and the camera works; the ticket logs 4 GB freed.", 5: 'A shop till cannot sign in to its account after a password change. You check the caps lock and keyboard language, reset through the verified owner, and the till is back in 10 minutes.', 6: "A guide 'Reset your email password in 6 steps' is tested by two new staff. One stalls at step 4, so you add a screenshot of the button; the second test passes in 3 minutes.", 7: 'In one week 30 tickets arrive; 24 get a first reply inside 30 minutes (80%), 21 are fixed first time (70%) and the average rating is 4.1. The weakest number is the reply time.', 8: 'Five users report the same slow login each Monday. You record the pattern, pass it to the system owner with times and screenshots, and the cause, a morning backup job, is moved to the evening.'}
C['deep']['mods'] = [(m[0], _dupfix.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ["You will follow a clear support cycle and agree response targets, so every user knows what happens after they report a problem.", "You will open each call with three diagnostic questions and repeat back key facts, which uncovers the real fault faster.", "You will write tickets with exact error text, steps to repeat and a priority based on impact, so any colleague can continue the case.", "You will work through an ordered checklist for slow, frozen or failing computers and phones, protecting user files before changing anything.", "You will separate single-account faults from network-wide ones and reset sign-ins safely, resolving many of the most frequent tickets quickly.", "You will write numbered how-to guides and test them on a newcomer, so the next user can solve the same issue without calling.", "You will track volume, reply time, fix time and satisfaction, and use repeat causes to decide where a guide or training would help most.", "You will recognise when to escalate and hand over complete notes, then use monthly reviews to turn difficult cases into lasting improvements."]
